using FluentValidation;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.OpenApi;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.OpenApi;
using Nexus.BuildingBlocks.Web.OpenApi;

namespace Nexus.BuildingBlocks.Web.Tests.OpenApi;

/// <summary>
/// Builds a real (unstarted) <see cref="WebApplication"/> with <c>AddNexusOpenApi()</c>, lets the
/// test register validators and map endpoints, and returns the OpenAPI document the host would
/// serve at <c>/openapi/v1.json</c> - generated by the same <c>Microsoft.AspNetCore.OpenApi</c>
/// pipeline, with every NEXUS transformer applied.
/// </summary>
internal static class OpenApiTestHost
{
    public static async Task<OpenApiDocument> GenerateAsync(
        Action<IServiceCollection> configureServices,
        Action<WebApplication> mapEndpoints)
    {
        var builder = WebApplication.CreateBuilder();
        builder.Services.AddNexusOpenApi();
        configureServices(builder.Services);

        await using var app = builder.Build();
        mapEndpoints(app);

        // Without starting the host, the app's endpoints only reach the global
        // EndpointDataSource (what ApiExplorer, and so the OpenAPI generator, reads) once the
        // routing middleware is wired - which a started WebApplication does implicitly.
        app.UseRouting();
        app.UseEndpoints(_ => { });

        var provider = app.Services.GetRequiredKeyedService<IOpenApiDocumentProvider>("v1");
        return await provider.GetOpenApiDocumentAsync(TestContext.Current.CancellationToken);
    }

    public static IServiceCollection AddValidator<T, TValidator>(this IServiceCollection services)
        where TValidator : class, IValidator<T> =>
        services.AddSingleton<IValidator<T>, TValidator>();

    public static OpenApiOperation Operation(this OpenApiDocument document, string path, HttpMethod method) =>
        document.Paths[path].Operations![method];

    public static OpenApiSchema ParameterSchema(this OpenApiOperation operation, string name) =>
        (OpenApiSchema)operation.Parameters!.Single(p => p.Name == name).Schema!;

    public static OpenApiSchema Component(this OpenApiDocument document, string name) =>
        (OpenApiSchema)document.Components!.Schemas![name];

    public static OpenApiSchema Property(this OpenApiSchema schema, string name) =>
        (OpenApiSchema)schema.Properties![name];
}
